// Package config 載入 app/config/config.yaml 的應用層設定（embedding / vector / rules）。
//
// @ai:generated by=claude-fable-5-1 date=2026-10-09
// @ai:purpose HypGo 的 config.Config 只涵蓋 server/db/logger，專案自有區段需另行解析；金鑰一律走環境變數
package config

import (
	"fmt"
	"os"
	"regexp"

	"gopkg.in/yaml.v3"
)

// AppConfig 為 config.yaml 的完整對應。
type AppConfig struct {
	App struct {
		Name    string `yaml:"name"`
		Version string `yaml:"version"`
	} `yaml:"app"`
	GRPC struct {
		Addr string `yaml:"addr"`
	} `yaml:"grpc"`
	Logger struct {
		Level  string `yaml:"level"`
		Output string `yaml:"output"`
		Colors bool   `yaml:"colors"`
	} `yaml:"logger"`
	Embedding EmbeddingConfig `yaml:"embedding"`
	Vector    VectorConfig    `yaml:"vector"`
	Rules     RulesConfig     `yaml:"rules"`
}

// EmbeddingConfig 對應 embedding 區段。
type EmbeddingConfig struct {
	Provider    string `yaml:"provider"`
	BaseURL     string `yaml:"base_url"`
	APIKey      string `yaml:"api_key"`
	Model       string `yaml:"model"`
	Concurrency int    `yaml:"concurrency"`
}

// VectorConfig 對應 vector 區段。
type VectorConfig struct {
	Path       string `yaml:"path"`
	Collection string `yaml:"collection"`
	Compress   bool   `yaml:"compress"`
}

// RulesConfig 對應 rules 區段。
type RulesConfig struct {
	DataDir          string   `yaml:"data_dir"`
	CacheDir         string   `yaml:"cache_dir"`
	CacheMaxAgeHours int      `yaml:"cache_max_age_hours"`
	CategoryPrefixes []string `yaml:"category_prefixes"`
	Names            []string `yaml:"names"`
	ExcludeRepealed  bool     `yaml:"exclude_repealed"`
}

// reEnv 支援 ${VAR} 與 ${VAR:-default} 兩種寫法。
var reEnv = regexp.MustCompile(`\$\{([A-Za-z_][A-Za-z0-9_]*)(?::-([^}]*))?\}`)

// Load 讀取 YAML、展開環境變數並套用預設值。
//
// @ai:generated by=claude-fable-5-1 date=2026-10-09
// @ai:purpose 單一入口載入設定，確保 CLI 與 gRPC 伺服器讀到同一份值
// @ai:input path config.yaml 路徑
// @ai:output *AppConfig, error
// @ai:sideeffect 讀檔、讀環境變數
func Load(path string) (*AppConfig, error) {
	raw, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("config: read %s: %w", path, err)
	}
	expanded := reEnv.ReplaceAllStringFunc(string(raw), func(m string) string {
		sub := reEnv.FindStringSubmatch(m)
		if v, ok := os.LookupEnv(sub[1]); ok && v != "" {
			return v
		}
		return sub[2]
	})
	var cfg AppConfig
	if err := yaml.Unmarshal([]byte(expanded), &cfg); err != nil {
		return nil, fmt.Errorf("config: parse %s: %w", path, err)
	}
	cfg.ApplyDefaults()
	return &cfg, nil
}

// ApplyDefaults 補上未設定欄位的合理預設值。
//
// @ai:generated by=claude-fable-5-1 date=2026-10-09
// @ai:purpose 讓最小 config 也能跑起來，且測試可直接建構 AppConfig{} 後呼叫
// @ai:input none
// @ai:output none
// @ai:sideeffect 修改 receiver 欄位
func (c *AppConfig) ApplyDefaults() {
	if c.GRPC.Addr == "" {
		c.GRPC.Addr = ":9090"
	}
	if c.Logger.Level == "" {
		c.Logger.Level = "info"
	}
	if c.Logger.Output == "" {
		c.Logger.Output = "stdout"
	}
	if c.Embedding.Provider == "" {
		c.Embedding.Provider = "lexical"
	}
	if c.Embedding.Concurrency <= 0 {
		c.Embedding.Concurrency = 4
	}
	if c.Vector.Path == "" {
		c.Vector.Path = "data/vectors"
	}
	if c.Vector.Collection == "" {
		c.Vector.Collection = "ly_rules"
	}
	if c.Rules.DataDir == "" {
		c.Rules.DataDir = "data/laws"
	}
	if c.Rules.CacheDir == "" {
		c.Rules.CacheDir = "data/raw"
	}
	if c.Rules.CacheMaxAgeHours == 0 {
		c.Rules.CacheMaxAgeHours = 720
	}
	if len(c.Rules.CategoryPrefixes) == 0 && len(c.Rules.Names) == 0 {
		c.Rules.CategoryPrefixes = []string{"立法"}
	}
}
